import { forwardRef, type ReactNode, useId } from "react";
import type { LucideIcon, LucideProps } from "./types";

// Brand logos for the external services an agent tool call can touch (Linear,
// Slack, Gmail, PostHog, …). Typed as LucideIcon so they drop into the same generic
// icon slots used across the app — the same `text-*` and `size-*` utilities that
// tint/size Lucide icons work here. Monochrome marks inherit `currentColor`;
// vendor artwork can preserve its own colors and gradients. The original 24x24
// paths are from Simple Icons (https://simpleicons.org). See service-icons.md
// for the vendor sources and adaptations of the newer plugin logos.

function brandIcon(
  displayName: string,
  artwork: string | ((id: string) => ReactNode),
  viewBox = "0 0 24 24",
): LucideIcon {
  const Icon = forwardRef<SVGSVGElement, LucideProps>(function BrandIcon(
    { size = 24, ...props },
    ref,
  ) {
    const id = useId();
    return (
      <svg
        ref={ref}
        xmlns="http://www.w3.org/2000/svg"
        width={size}
        height={size}
        viewBox={viewBox}
        fill="currentColor"
        aria-hidden="true"
        {...props}
      >
        {typeof artwork === "string" ? <path d={artwork} /> : artwork(id)}
      </svg>
    );
  });
  Icon.displayName = displayName;
  return Icon;
}

